package cn.sixnine.filmlog;

import android.app.*;
import android.content.*;
import android.os.*;
import android.graphics.*;
import android.view.*;
import android.widget.*;
import java.util.*;

/** Synthetic workspace only; physical camera calibration and background device policy are not covered. */
public final class ToolsUiInstrumentation extends Instrumentation {
    public static final class Host extends Activity {static volatile Intent answer;static volatile int code;@Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);code=result;answer=data;}}
    private Bundle args;private Activity current;private String roll,custom;
    interface Probe{void run()throws Exception;}
    private void check(boolean ok,String text){if(!ok)throw new AssertionError(text);}
    private Object get(Object owner,String name)throws Exception{java.lang.reflect.Field f=owner.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(owner);}
    private Object call(Object owner,String name,Class<?>[] types,Object... values)throws Exception{java.lang.reflect.Method m=owner.getClass().getDeclaredMethod(name,types);m.setAccessible(true);return m.invoke(owner,values);}
    private void main(Probe action)throws Exception{Throwable[] bad={null};runOnMainSync(()->{try{action.run();}catch(Throwable e){bad[0]=e;}});waitForIdleSync();if(bad[0]!=null)throw new RuntimeException(bad[0]);}
    private Activity launch(Class<?> type,Intent extra){current=startActivitySync(extra.setClass(getTargetContext(),type).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();return current;}
    @SuppressWarnings("unchecked") private EditText input(String key)throws Exception{return ((Map<String,EditText>)get(current,"inputs")).get(key);}
    private Button find(View root,String label){if(root instanceof Button&&((Button)root).getText().toString().equals(label))return (Button)root;if(root instanceof ViewGroup)for(int i=0;i<((ViewGroup)root).getChildCount();i++){Button b=find(((ViewGroup)root).getChildAt(i),label);if(b!=null)return b;}return null;}
    private void layout(Activity activity)throws Exception{View root=activity.getWindow().getDecorView();float density=activity.getResources().getDisplayMetrics().density;for(int width:new int[]{320,375,414,768}){root.measure(View.MeasureSpec.makeMeasureSpec(Math.round(width*density),View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(Math.round(680*density),View.MeasureSpec.EXACTLY));root.layout(0,0,root.getMeasuredWidth(),root.getMeasuredHeight());inspect(root,root.getWidth(),density);}root.requestLayout();}
    private void inspect(View view,int max,float density){if(view.getVisibility()!=View.VISIBLE)return;check(view.getWidth()<=max+1,"view wider than page");if(view instanceof Button){Button b=(Button)view;check(b.getLineCount()<=1,"wrapped action: "+b.getText());check(b.getHeight()>=Math.round(44*density),"small touch target: "+b.getText());}if(view instanceof ViewGroup)for(int i=0;i<((ViewGroup)view).getChildCount();i++)inspect(((ViewGroup)view).getChildAt(i),max,density);}
    private void fixture(Context context)throws Exception{try(LogStore logs=new LogStore(context)){FilmStockStore.Stock stock=new FilmStockStore.Stock();custom=stock.id=UUID.randomUUID().toString();stock.brand="Test";stock.name="Custom 400";stock.iso=400;stock.process="C-41";stock.power="1.5";stock.formats="35 mm";new FilmStockStore(logs).save(stock);roll=new CatalogStore(logs).manual(UUID.randomUUID().toString(),"午后散步","Kodak Ultramax 400","Leica M6",400,36,"35 mm","","","original:kodak_ultramax_400");for(int i=1;i<=6;i++){if(i<5)logs.insert(roll,1792970000000L+i*60000,-10,480,"denied","8","1/125","","","","");else{Bitmap image=Bitmap.createBitmap(360,240,Bitmap.Config.ARGB_8888);Canvas c=new Canvas(image);c.drawColor(i==5?0xff8cafa2:0xffab8870);Paint p=new Paint(3);p.setColor(0xff3d5148);c.drawRect(0,150,360,240,p);p.setColor(0xffded5bf);c.drawRect(40,60,170,210,p);p.setColor(0xffa34f36);c.drawCircle(270,65,28,p);String token=UUID.randomUUID().toString();ReferencePhotos.capture(context,token,image);image.recycle();ReferencePhotos.record(context,logs,token,roll,1792970000000L+i*60000,-10,480,"denied","8","1/125","","","","");}}context.getSharedPreferences("cn.sixnine.filmlog.MainActivity",0).edit().putString("dashboard_roll",roll).commit();}}
    private void film(Context context)throws Exception{try(LogStore logs=new LogStore(context)){ArrayList<LogStore.Shot> frames=logs.shots(roll);main(()->{ContactSheet sheet=ContactSheet.film(context,logs,roll,frames,id->{});try{float density=context.getResources().getDisplayMetrics().density;for(int width:new int[]{280,335,374,728}){int pixels=Math.round(width*density);sheet.measure(View.MeasureSpec.makeMeasureSpec(pixels,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(0,View.MeasureSpec.UNSPECIFIED));sheet.layout(0,0,pixels,sheet.getMeasuredHeight());float scale=(Float)call(sheet,"stripScale",new Class<?>[]{}),height=(Float)call(sheet,"filmPhotoHeight",new Class<?>[]{});check(Math.abs(36*scale/height-1.5)<.001,"135 photo stays 3:2");int columns=(Integer)get(sheet,"columns");check(columns==7,"full-frame preview keeps the confirmed seven columns");check(sheet.getMeasuredHeight()>35*scale,"complete bottom perforations and labels");} }finally{sheet.onDetachedFromWindow();}});}}
    @Override public void onCreate(Bundle params){args=params;super.onCreate(params);start();}
    @Override public void onStart(){Context context=getTargetContext();Bundle out=new Bundle();String previous=Workspace.current(context);boolean pass=false,preview=args!=null&&"preview".equals(args.getString("mode"));try{
        check(context.getPackageName().equals("cn.sixnine.filmlog.ui.tests"),"isolated UI package");String workspace=UUID.randomUUID().toString();Workspace.activate(context,workspace);Context isolated=new WorkspaceContext(Workspace.root(context),workspace);fixture(isolated);if(preview){out.putString("stream","PREVIEW workspace="+workspace+" roll="+roll+"; synthetic photos and records only\n");pass=true;}else{
        film(isolated);launch(PhotoToolsActivity.class,new Intent().putExtra("tool_mode",0));main(()->{check(Math.abs((Double)get(current,"computedSeconds")-1.0/512)<1e-10,"initial EV result");input("comp").setText("1");check(Math.abs((Double)get(current,"computedSeconds")-1.0/256)<1e-10,"live compensation");input("iso").setText("");check(get(current,"computedAnswer")==null&&!((Button)get(current,"applyResult")).isEnabled(),"invalid disables stale result");input("iso").setText("100");input("comp").setText("0");input("ev100").setText("0");check(Math.abs((Double)get(current,"computedSeconds")-64)<1e-8,"64 sec result");layout(current);});
        ActivityMonitor timerMonitor=addMonitor(ExposureTimerActivity.class.getName(),null,false);main(()->((Button)get(current,"timerResult")).performClick());ExposureTimerActivity timer=(ExposureTimerActivity)timerMonitor.waitForActivityWithTimeout(5000);check(timer!=null&&timer.getIntent().getLongExtra("duration_ms",0)==64000,"calculated exact duration opens timer");removeMonitor(timerMonitor);main(()->timer.finish());
        main(()->{find(current.getWindow().getDecorView(),"固定快门").performClick();check((Integer)get(current,"priority")==1,"priority switch");input("ev100").setText("15");check(get(current,"computedAnswer")!=null,"shutter priority recalculates");Intent meter=new Intent().putExtra("ev100",14d).putExtra("meter_iso",400);call(current,"onActivityResult",new Class<?>[]{int.class,int.class,Intent.class},50,Activity.RESULT_OK,meter);check(input("iso").getText().toString().equals("400")&&input("ev100").getText().toString().equals("14"),"meter result fills EV and ISO");current.finish();});
        launch(PhotoToolsActivity.class,new Intent().putExtra("tool_mode",1));main(()->{input("nd").setText("10");check(Math.abs((Double)get(current,"computedSeconds")-8.192)<1e-8,"ND result");((Spinner)get(current,"filmChoice")).setSelection(1);});main(()->{check(Math.abs((Double)get(current,"computedSeconds")-Math.pow(8.192,1.31))<1e-8,"selected film live reciprocity");((Spinner)get(current,"filmChoice")).setSelection(PhotoMath.FILMS.length);});main(()->{check(Math.abs((Double)get(current,"computedSeconds")-Math.pow(8.192,1.5))<1e-8,"custom coefficient live result");try(LogStore logs=new LogStore(current)){new FilmStockStore(logs).archive(custom,true);}input("nd").setText("9");check(get(current,"computedAnswer")==null,"archived custom film never silently reused");call(current,"show",new Class<?>[]{});check((Integer)get(current,"missingFilmIndex")>=PhotoMath.FILMS.length&&get(current,"computedAnswer")==null,"unavailable selection retained as explicit error");((Spinner)get(current,"filmChoice")).setSelection(0);});main(()->{input("nd").setText("-1");check(get(current,"computedAnswer")==null&&((Button)get(current,"timerResult")).getVisibility()==View.GONE,"invalid ND hides stale timer");input("nd").setText("0");layout(current);current.finish();});
        launch(PhotoToolsActivity.class,new Intent().putExtra("tool_mode",2));main(()->{check(((TextView)get(current,"result")).getText().toString().contains("2.34–4.19"),"depth interval rounded for display only");check(call(current,"distanceText",new Class<?>[]{double.class},.001).equals("<0.01"),"tiny distance never shown as zero");check(((View)get(current,"advancedFields")).getVisibility()==View.GONE,"advanced collapsed with default visible hint");input("distance").setText("100");check(((TextView)get(current,"result")).getText().toString().contains("∞"),"far boundary infinity");input("circle").setText("0.04");check(((TextView)get(current,"circleHint")).getText().toString().contains("0.04"),"advanced affects results");input("distance").setText("0");check(get(current,"computedAnswer")==null,"invalid distance");input("distance").setText("3");layout(current);current.finish();});
        launch(PhotoToolsActivity.class,new Intent().putExtra("tool_mode",3));main(()->{check(((TextView)get(current,"result")).getText().toString().equals("f/4"),"flash preserved");layout(current);current.finish();});
        Host host=(Host)startActivitySync(new Intent(context,Host.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));ActivityMonitor toolMonitor=addMonitor(PhotoToolsActivity.class.getName(),null,false);main(()->host.startActivityForResult(new Intent(host,PhotoToolsActivity.class).putExtra("return_result",true).putExtra("iso",400),7));PhotoToolsActivity returned=(PhotoToolsActivity)toolMonitor.waitForActivityWithTimeout(5000);removeMonitor(toolMonitor);current=returned;main(()->{check(!input("iso").isEnabled(),"draft ISO remains locked");((Button)get(current,"applyResult")).performClick();});for(int retry=0;retry<40&&Host.answer==null;retry++){waitForIdleSync();SystemClock.sleep(50);}main(()->{check(Host.code==Activity.RESULT_OK&&Host.answer!=null&&Host.answer.hasExtra("shutter")&&Host.answer.hasExtra("aperture"),"draft return contract preserved");host.finish();});
        launch(ExposureTimerActivity.class,new Intent());main(()->{find(current.getWindow().getDecorView(),"2分钟").performClick();check(((EditText)get(current,"minutes")).getText().toString().equals("2")&&find(current.getWindow().getDecorView(),"2分钟").isSelected(),"preset duration and selected state");((EditText)get(current,"partSeconds")).setText("60");check(!((Button)get(current,"start")).isEnabled(),"invalid seconds disables start");((EditText)get(current,"partSeconds")).setText("0");layout(current);((Button)get(current,"start")).performClick();check(ExposureClock.read(current).status.equals("running"),"start uses persistent clock");check(((View)get(current,"durationControls")).getVisibility()==View.GONE,"running hides inputs");});main(()->{((Button)get(current,"pause")).performClick();check(ExposureClock.read(current).status.equals("paused"),"pause preserved");});main(()->{((Button)get(current,"resume")).performClick();check(ExposureClock.read(current).status.equals("running"),"resume preserved");});main(()->{((Button)get(current,"cancel")).performClick();check(ExposureClock.read(current).status.equals("cancelled"),"cancel preserved");current.finish();});
        out.putString("stream","PASS: film3:2/KS geometry/responsive targets; live EV/ND/reciprocity/depth/advanced/invalid suppression; meter and draft result contracts; exact duration transfer; timer presets/minute-second validation/start/pause/resume/cancel; layout320/375/414/768. Synthetic workspace="+workspace+"\n");pass=true;}
    }catch(Throwable bad){out.putString("stream",android.util.Log.getStackTraceString(bad));}finally{if(!preview){try{if(current!=null)main(()->{ExposureClock.cancel(current);current.stopService(new Intent(current,ExposureTimerService.class));current.finish();});}catch(Exception ignored){}Workspace.activate(context,previous);}}finish(pass?-1:0,out);}
}
